import pandas as pd
import numpy as np


def _norm(v):
    """Normalize a value for NULL-safe comparison: NaN/None -> None."""
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    return v


def _norm_eq(a, b):
    return _norm(a) == _norm(b)


def _apply_field(current, change_val, is_email=False):
    """Apply the change-field rule: NaN -> unchanged, '<<NULL>>' -> NULL,
    else -> new value (email is lower/trim)."""
    if pd.isna(change_val):
        return current
    if change_val == '<<NULL>>':
        return np.nan
    if is_email:
        return change_val.strip().lower()
    return change_val


def _init_field(change_val, is_email=False):
    """Field value when creating a brand-new customer from a change."""
    if pd.isna(change_val):
        return np.nan
    if change_val == '<<NULL>>':
        return np.nan
    if is_email:
        return change_val.strip().lower()
    return change_val


def run(inputs):
    customer_profile = inputs["customer_profile"]
    profile_changes = inputs["profile_changes"]

    profiles = {}
    for row in customer_profile.itertuples(index=False):
        profiles[row.customer_id] = {
            'email': row.email,
            'phone': row.phone,
            'tier': row.tier,
            'updated_seq': row.updated_seq,
        }

    # Deterministic ordering: process changes by customer_id, then by change_seq.
    changes_sorted = profile_changes.sort_values(['customer_id', 'change_seq'],
                                                  kind='mergesort')

    for cid, group in changes_sorted.groupby('customer_id', sort=False):
        for chg in group.itertuples(index=False):
            change_seq = chg.change_seq
            email_c = chg.email
            phone_c = chg.phone
            tier_c = chg.tier

            if cid not in profiles:
                # Create a new customer row from this change.
                profiles[cid] = {
                    'email': _init_field(email_c, is_email=True),
                    'phone': _init_field(phone_c),
                    'tier': _init_field(tier_c),
                    'updated_seq': change_seq,
                }
                continue

            p = profiles[cid]

            if change_seq <= p['updated_seq']:
                # Stale change, skip.
                continue

            new_email = _apply_field(p['email'], email_c, is_email=True)
            new_phone = _apply_field(p['phone'], phone_c)
            new_tier = _apply_field(p['tier'], tier_c)

            unchanged = (
                _norm_eq(new_email, p['email']) and
                _norm_eq(new_phone, p['phone']) and
                _norm_eq(new_tier, p['tier'])
            )

            if unchanged:
                # No-op: watermark does NOT advance, values stay the same.
                continue

            p['email'] = new_email
            p['phone'] = new_phone
            p['tier'] = new_tier
            p['updated_seq'] = change_seq

    if profiles:
        out_rows = [
            {
                'customer_id': cid,
                'email': vals['email'],
                'phone': vals['phone'],
                'tier': vals['tier'],
                'updated_seq': vals['updated_seq'],
            }
            for cid, vals in profiles.items()
        ]
        new_profile = pd.DataFrame(
            out_rows,
            columns=['customer_id', 'email', 'phone', 'tier', 'updated_seq']
        )
        new_profile = new_profile.sort_values('customer_id', kind='mergesort').reset_index(drop=True)
        new_profile['customer_id'] = new_profile['customer_id'].astype('int64')
        new_profile['updated_seq'] = new_profile['updated_seq'].astype('int64')
    else:
        new_profile = pd.DataFrame(
            columns=['customer_id', 'email', 'phone', 'tier', 'updated_seq']
        )
        new_profile['customer_id'] = new_profile['customer_id'].astype('int64')
        new_profile['updated_seq'] = new_profile['updated_seq'].astype('int64')

    return {'new_profile': new_profile}
